CREATE TABLE company (id BIGINT IDENTITY PRIMARY KEY, company_name NVARCHAR(200), street NVARCHAR(200), postal_code NVARCHAR(20), city NVARCHAR(100), country NVARCHAR(100), tax_number NVARCHAR(100), vat_id NVARCHAR(100));
CREATE TABLE bank_account (id BIGINT IDENTITY PRIMARY KEY, company_id BIGINT, bank_name NVARCHAR(120), account_holder NVARCHAR(200), iban NVARCHAR(34), bic NVARCHAR(11), default_account BIT, active BIT);
CREATE TABLE customer (id BIGINT IDENTITY PRIMARY KEY, customer_number NVARCHAR(30), company_name NVARCHAR(200), first_name NVARCHAR(100), last_name NVARCHAR(100), street NVARCHAR(200), postal_code NVARCHAR(20), city NVARCHAR(100), country NVARCHAR(100), email NVARCHAR(200), phone NVARCHAR(100), vat_id NVARCHAR(100), default_payment_term_days INT, default_discount_percent DECIMAL(5,2), default_discount_days INT, active BIT);
CREATE TABLE product (id BIGINT IDENTITY PRIMARY KEY, product_number NVARCHAR(30), name NVARCHAR(200), description NVARCHAR(1000), unit NVARCHAR(30), net_price DECIMAL(19,4), vat_rate DECIMAL(5,2), active BIT);
CREATE TABLE invoice (id BIGINT IDENTITY PRIMARY KEY, invoice_number NVARCHAR(30), invoice_date DATE, service_date DATE, customer_id BIGINT, bank_account_id BIGINT, status NVARCHAR(30), payment_term_days INT, due_date DATE, discount_percent DECIMAL(5,2), discount_days INT, customer_name NVARCHAR(200), bank_name NVARCHAR(120), iban NVARCHAR(34), bic NVARCHAR(11), subtotal_net DECIMAL(19,2), tax_amount DECIMAL(19,2), total_gross DECIMAL(19,2), notes NVARCHAR(2000));
CREATE TABLE invoice_item (id BIGINT IDENTITY PRIMARY KEY, invoice_id BIGINT REFERENCES invoice(id), position_number INT, product_id BIGINT, product_number NVARCHAR(30), description NVARCHAR(1000), quantity DECIMAL(19,3), unit NVARCHAR(30), unit_price_net DECIMAL(19,4), discount_percent DECIMAL(5,2), vat_rate DECIMAL(5,2), line_net DECIMAL(19,2), tax_amount DECIMAL(19,2), line_gross DECIMAL(19,2));
